using System.Windows;using OncaPDV.Infrastructure;namespace OncaPDV.Desktop;public partial class Reports022Window:Window{private readonly ReportService022 _svc;private readonly AppPaths _paths;private Report022? _report;public Reports022Window(OncaDatabase db,AppPaths paths){_svc=new(db);_paths=paths;InitializeComponent();FromPicker.SelectedDate=DateTime.Today;ToPicker.SelectedDate=DateTime.Today;Loaded+=async(_,_)=>await Refresh();}private (DateTimeOffset From,DateTimeOffset To)Range(){var f=(FromPicker.SelectedDate??DateTime.Today).Date;var t=(ToPicker.SelectedDate??DateTime.Today).Date.AddDays(1);return(f,t);}private async Task Refresh(){var r=Range();_report=await _svc.LoadAsync(r.From,r.To);SalesText.Text=_report.Sales.ToString();RevenueText.Text=_report.Revenue.ToString("C");OrdersText.Text=_report.PaidOrders.ToString();CancelledText.Text=_report.CancelledSales.ToString();CashText.Text=$"Dinheiro: {_report.Cash:C}";PixText.Text=$"PIX: {_report.Pix:C}";DebitText.Text=$"Débito: {_report.Debit:C}";CreditText.Text=$"Crédito: {_report.Credit:C}";StoreCreditText.Text=$"Crediário gerado: {_report.StoreCredit:C}";CreditReceiptsText.Text=$"Crediário recebido: {_report.CreditReceipts:C}";}private async void Refresh_Click(object sender,RoutedEventArgs e)=>await Refresh();private async void Pdf_Click(object sender,RoutedEventArgs e){await Refresh();var r=Range();var file=await _svc.PdfAsync(_report!,r.From,r.To,_paths);MessageBox.Show($"PDF GERADO\n\n{file}","Relatório",MessageBoxButton.OK,MessageBoxImage.Information);}}